const $=s=>document.querySelector(s);let token='',data;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function status(s,error=false){$('#status').textContent=s;$('#status').className=error?'admin-error':''}
async function api(path,body){const r=await fetch('/api/admin/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'请求失败');return d}
async function refresh(){data=await api('state');const selected=$('#person-id').value;$('#person-id').innerHTML=data.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.role||'身份待补充')}</option>`).join('');if(data.people.some(p=>p.id===selected))$('#person-id').value=selected;render();$('#workspace').hidden=false}
function render(){renderAI();renderRequests();renderSources();const f=$('#filter').value;const rows=data.candidates.filter(c=>f==='all'||c.status===f);$('#candidates').innerHTML=rows.map(c=>`<article class="review" data-id="${esc(c.id)}"><div class="meta">${esc(data.people.find(p=>p.id===c.person_id)?.name||c.person_id)} · ${esc(c.show)} · ${{pending:'待核验',approved:'已发布',rejected:'已驳回'}[c.status]||esc(c.status)}</div><h3>${esc(c.title)}</h3><p><a href="${esc(c.source)}" target="_blank" rel="noopener">查看原始单集说明 ↗</a></p><details><summary>查看来源描述（待核验）</summary><p>${esc(c.description||'没有描述，请打开原始来源核验。')}</p></details><label>参与依据 / 纠错原因<textarea data-evidence placeholder="写明来源页面、嘉宾身份和参与依据；只提及该人物不能发布。">${esc(c.evidence||'')}</textarea></label><button class="primary" data-review="approved">确认本人参与并发布</button><button data-review="rejected">驳回 / 撤回</button><button data-review="pending">退回待核验</button></article>`).join('')||'<p class="sub">当前没有符合条件的候选。可以先导入 RSS。</p>';$('#runs').innerHTML=(data.runs||[]).map(r=>`<div class="review"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(r,null,2))}</pre></div>`).join('')||'<p class="sub">尚未导入。</p>'}
$('#auth').onsubmit=async e=>{e.preventDefault();token=$('#token').value.trim();status('正在连接…');try{await refresh();status('已连接本地目录')}catch(e){$('#workspace').hidden=true;status(e.message,true)}};
$('#filter').onchange=render;
$('#import').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;status('正在读取 RSS 并查找候选…');try{const r=await api('import',{feed_url:$('#feed').value,person_id:$('#person-id').value});await refresh();status('导入完成。已配置的 AI 会判断候选，结果见自动审核记录。')}catch(e){status(e.message,true);try{await refresh()}catch{}}finally{b.disabled=false}};
$('#person').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('person',Object.fromEntries(new FormData(e.target)));await refresh();e.target.reset();status('人物已保存，审核通过出场后会出现在公开目录。')}catch(e){status(e.message,true)}finally{b.disabled=false}};
$('#candidates').onclick=async e=>{const b=e.target.closest('[data-review]');if(!b)return;const row=b.closest('[data-id]');const evidence=row.querySelector('textarea').value.trim();if(b.dataset.review==='approved'&&!evidence){status('请先填写本人参与的依据。',true);row.querySelector('textarea').focus();return}b.disabled=true;try{await api('review',{id:row.dataset.id,status:b.dataset.review,evidence});await refresh();status('审核已保存，人物页刷新后生效。')}catch(e){status(e.message,true);b.disabled=false}};

const requestLabels={queued:'已排队',researching:'查找中',reviewing:'待核验',completed:'已完成',not_found:'暂未找到'};
function renderRequests(){$('#requests').innerHTML=(data.requests||[]).map(r=>`<article class="review" data-request-id="${esc(r.id)}"><h3>${esc(r.query)}</h3><p>${esc(r.identity_hint||'没有额外身份线索')}</p><label>处理状态<select data-request-status>${Object.entries(requestLabels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>处理说明<textarea data-request-note>${esc(r.note)}</textarea></label><label>关联人物（标记完成时必选，且已有审核通过出场）<select data-request-person><option value="">尚未关联</option>${data.people.map(p=>`<option value="${esc(p.id)}" ${r.person_id===p.id?'selected':''}>${esc(p.name)} · ${esc(p.role||'')}</option>`).join('')}</select></label><button data-save-request>保存处理结果</button><details><summary>处理历史</summary>${(r.history||[]).map(h=>`<p>${esc(requestLabels[h.status]||h.status)} · ${esc(h.note)} · ${esc(h.created_at)}</p>`).join('')}</details></article>`).join('')||'<p class="sub">暂无人物补录请求。</p>';}
$('#requests').onclick=async e=>{const b=e.target.closest('[data-save-request]');if(!b)return;const row=b.closest('[data-request-id]');b.disabled=true;try{await api('request',{id:row.dataset.requestId,status:row.querySelector('[data-request-status]').value,note:row.querySelector('[data-request-note]').value,person_id:row.querySelector('[data-request-person]').value});await refresh();status('补录处理结果已保存。')}catch(e){status(e.message,true);b.disabled=false}};

function renderSources(){const labels={completed:'检查成功',failed:'检查失败',running:'正在检查'};const stamp=v=>v?new Date(v).toLocaleString('zh-CN'):'尚无成功记录';$('#sources').innerHTML=(data.sources||[]).map(source=>`<article class="review" data-source-id="${esc(source.id)}"><div class="meta">${esc(data.people.find(p=>p.id===source.person_id)?.name||source.person_id)} · ${esc(labels[source.status]||source.status)}</div><p>${esc(source.feed_url)}</p><p>最近检查：${esc(stamp(source.last_checked_at))}<br>最近成功：${esc(stamp(source.last_success_at))}</p>${source.status==='completed'?`<p>匹配 ${source.matched} 条 · 新增 ${source.added} 条待核验候选</p>`:''}${source.error?`<p class="admin-error">${esc(source.error)}</p>`:''}<button data-refresh-source>${source.status==='failed'?'重试来源':'检查新出场'}</button></article>`).join('')||'<p class="sub">首次导入 RSS 后，来源会保存在这里。</p>';}
let sourceRefreshBusy=false;
$('#sources').onclick=async event=>{const button=event.target.closest('[data-refresh-source]');if(!button||sourceRefreshBusy)return;sourceRefreshBusy=true;const id=button.closest('[data-source-id]').dataset.sourceId;document.querySelectorAll('[data-refresh-source]').forEach(b=>b.disabled=true);button.textContent='正在检查…';status('正在检查 RSS，新出场将进入待核验…');try{const result=await api('refresh',{id});await refresh();status(result.added?`检查完成：新增 ${result.added} 条候选；AI 处理结果见自动审核记录。`:'检查完成：没有新增候选。');}catch(error){status(error.message,true);try{await refresh()}catch{}}finally{sourceRefreshBusy=false;document.querySelectorAll('[data-refresh-source]').forEach(b=>b.disabled=false);}};

function renderAI(){$('#ai-status').textContent=data.ai?.configured?'节省模式：规则优先，单集参与者提取一次并复用，原文证据校验后发布。':'模型尚未配置：请在服务端设置 OPENAI_API_KEY 和 TINGSHUI_AI_MODEL；仅处理已验证来源规则，不调用模型。';$('#ai-runtime').textContent='队列：'+({unconfigured:'等待模型配置',processing:'处理中',waiting:'等待新任务或重试',budget_paused:'今日模型额度已用完，缓存和规则仍可处理',error:'处理失败',stopped:'已停止',not_started:'未启动'}[data.ai?.runtime?.status]||'未知')+' · '+(data.ai?.runtime?.updated_at?new Date(data.ai.runtime.updated_at).toLocaleString('zh-CN'):'');$('#ai-budget').textContent=data.ai?.budget?`今日模型调用 ${data.ai.budget.used} / ${data.ai.budget.limit} 次（UTC日界线，失败也计入；不是金额上限）`:'';$('#ai-run').disabled=false;$('#ai-recent').innerHTML=(data.ai?.recent||[]).map(r=>`<p>${esc(r.candidate_id)} · ${esc(r.outcome)} · ${esc(r.created_at)}</p><details><summary>判断依据</summary><p>${esc(r.detail)}</p></details>`).join('');}
$('#ai-run').onclick=async()=>{const b=$('#ai-run');b.disabled=true;status('正在唤醒后台队列…');try{const r=await api('ai-review',{});await refresh();status(r.configured?'后台队列已唤醒，无需停留在此页面。':'规则队列已唤醒；模型未配置，不会调用模型。');}catch(e){status(e.message,true);}finally{b.disabled=false;}};

$('#ai-refresh').onclick=async()=>{try{await refresh();status('队列状态已更新。');}catch(e){status(e.message,true);}};
